<script setup lang="ts">
import { ArrowLeft, Minus, Plus, ShoppingBag, PackageCheck, Heart } from 'lucide-vue-next'
import type { Product } from '../../shared'
import { formatPrice, categoryName } from '../../shared'
const route = useRoute()
const { data: product, error } = await useFetch<Product>(() => '/api/products/' + route.params.slug)
if (error.value) throw createError({ statusCode: 404, statusMessage: 'محصول پیدا نشد.' })
const images = computed(() => { try { return [product.value?.image, ...JSON.parse(product.value?.gallery || '[]')].filter(Boolean) as string[] } catch { return product.value?.image ? [product.value.image] : [] } })
const selectedImage = ref('')
watch(product, () => { selectedImage.value = product.value?.image || '' }, { immediate: true })
const quantity = ref(1)
const added = ref(false)
const { add } = useCart()
function addToCart() { for (let i = 0; i < quantity.value; i++) add(product.value!.id, product.value!.stock); added.value = true; setTimeout(() => added.value = false, 2500) }
useSeoMeta({ title: () => `${product.value?.name || 'محصول'} | پیله پاتری`, description: () => product.value?.description || '' })
</script>
<template><div v-if="product" class="container detail-page"><div class="breadcrumbs"><NuxtLink to="/">خانه</NuxtLink><span>/</span><NuxtLink to="/products">فروشگاه</NuxtLink><span>/</span><span>{{ product.name }}</span></div><div class="detail-grid"><div class="detail-gallery"><div class="detail-photo"><img :src="selectedImage || product.image" :alt="product.name"/></div><div v-if="images.length > 1" class="detail-thumbs"><button v-for="(image,index) in images" :key="image" :class="{chosen:(selectedImage || product.image)===image}" :aria-label="'نمای '+(index+1)+' از '+product.name" @click="selectedImage=image"><img :src="image" :alt="'نمای '+(index+1)"/></button></div></div><div class="detail-info"><span class="eyebrow">HANDCRAFTED PIECE</span><div class="category-label">{{ categoryName(product.category) }}</div><h1>{{ product.name }}</h1><span class="detail-rule"></span><p class="detail-description">{{ product.description }}</p><div class="detail-price">{{ formatPrice(product.price) }} <small>تومان</small></div><div class="detail-stock">{{ product.stock ? `موجود (${formatPrice(product.stock)} عدد)` : 'در حال حاضر ناموجود' }}</div><div class="purchase-row"><div class="quantity-picker"><button :disabled="quantity<=1" aria-label="کاهش تعداد" @click="quantity--"><Minus :size="16"/></button><span>{{ quantity }}</span><button :disabled="quantity>=product.stock" aria-label="افزایش تعداد" @click="quantity++"><Plus :size="16"/></button></div><button class="btn buy-button" :disabled="!product.stock" @click="addToCart"><ShoppingBag :size="18"/> افزودن به سبد خرید <ArrowLeft :size="16"/></button></div><p v-if="added" class="success-msg">به سبد خرید اضافه شد. <NuxtLink to="/cart"><u>مشاهده‌ی سبد</u></NuxtLink></p><div class="detail-benefits"><span><Heart :size="19" :stroke-width="1.4"/> ساخته‌شده با عشق</span><span><PackageCheck :size="19" :stroke-width="1.4"/> بسته‌بندی امن و زیبا</span></div><p class="handmade-note">* به دلیل دست‌ساز بودن، هر قطعه ممکن است تفاوت‌های کوچکی در رنگ و فرم داشته باشد؛ همین تفاوت‌ها آن را یکتا می‌کند.</p></div></div><div class="detail-end"><span>یک انتخاب از جنس حالِ خوب.</span><NuxtLink to="/products" class="text-link">بازگشت به فروشگاه <ArrowLeft :size="16"/></NuxtLink></div></div></template>
<style scoped>.detail-page{padding-top:38px;padding-bottom:100px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(45px,8vw,130px);align-items:center}.detail-photo{aspect-ratio:1/1.06;background:var(--cream)}.detail-thumbs{display:flex;gap:10px;margin-top:12px;overflow-x:auto}.detail-thumbs button{width:70px;height:76px;padding:0;border:1px solid transparent;background:var(--cream);flex:none}.detail-thumbs button.chosen{border-color:var(--rust)}.detail-thumbs img{width:100%;height:100%;object-fit:cover}.detail-photo img{width:100%;height:100%;object-fit:cover}.detail-info{padding:20px 0}.detail-info .eyebrow{justify-content:flex-end}.category-label{color:var(--rust);font-size:13px;margin-top:30px}.detail-info h1{font-size:clamp(35px,4vw,57px);font-weight:500;letter-spacing:-.04em;margin:7px 0 22px}.detail-rule{display:block;width:47px;height:1px;background:var(--rust)}.detail-description{font-size:15px;line-height:2.4;color:#74786c;margin:32px 0;max-width:480px}.detail-price{font-size:25px;color:var(--olive);font-weight:500}.detail-price small{font-size:13px;font-weight:400}.detail-stock{font-size:12px;color:var(--muted);margin:8px 0 25px}.purchase-row{display:flex;gap:12px}.quantity-picker{display:flex;align-items:center;border:1px solid var(--line);height:52px}.quantity-picker button{border:0;background:none;width:37px;height:100%;display:grid;place-items:center}.quantity-picker button:disabled{opacity:.3}.quantity-picker span{min-width:27px;text-align:center;font-size:13px}.buy-button{flex:1;gap:13px}.detail-info .success-msg{margin:15px 0 0}.detail-benefits{border-top:1px solid var(--line);margin-top:37px;padding-top:20px;display:flex;gap:25px;color:#687062;font-size:12px}.detail-benefits span{display:flex;gap:8px;align-items:center}.handmade-note{font-size:11px;color:#96998e;line-height:2;margin-top:25px}.detail-end{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);margin-top:100px;padding-top:30px;color:var(--muted);font-size:14px}@media(max-width:750px){.detail-grid{gap:30px}.detail-info h1{font-size:33px}.purchase-row{flex-wrap:wrap}.buy-button{min-width:100%}}@media(max-width:650px){.detail-page{padding-top:25px;padding-bottom:65px}.detail-grid{grid-template-columns:1fr}.detail-info{padding:0}.detail-photo{aspect-ratio:1/1}.detail-info .eyebrow{margin-top:12px}.detail-description{font-size:13px;margin:22px 0}.detail-end{margin-top:50px}}</style>
